    scale = ((float *)((Moby *)m)->pvars);
    copy_matrix_rotation(transform, m + 0xC0);
    qcopy(position, m + 0x10);
    position[3] = 1.0f;
    first.tex = GetEffectTex(0x2C);
    first.unk80 = 0xFF9000000260L;
    first.unk70 = 0;
    second.tex = GetEffectTex(0x2C);
    second.unk80 = 0xFF9000000260L;
    second.unk70 = 0;
    second.col[3] = 0;
    second.col[1] = 0;
    sv = &second;
    pb = (float *)sv;
    qb = (float *)sv;
    pa = (float *)&first;
    s1 = orxon_quad_layer_first_vertices;
    s2 = orxon_quad_layer_second_vertices;
